// convex/r2.ts  --  APPLICATION CODE (counted)
//
// WRITTEN TO SPEC. NOT EXECUTED.
//
// WHY R2 AND NOT CONVEX FILE STORAGE
// ----------------------------------
// Convex's own File Storage docs say, twice, in bold:
//
//   "File URLs generated by storage.getUrl() are different: anyone with the
//    URL can access the file without another app-level authorization check.
//    The only way to revoke a file URL is by deleting the file."
//   -- https://docs.convex.dev/file-storage/overview
//
// and then:
//
//   "If you need file URLs that automatically expire after some time, consider
//    the Cloudflare R2 component."
//   -- https://docs.convex.dev/file-storage/serve-files
//
// The Vault scenario requires share links with an expiry, so the docs steer
// directly here. `convex/variantA_convexFileStorage.ts` shows the pure Convex
// File Storage implementation and exactly where it fails the scenario.
//
// Component docs: https://www.convex.dev/components/cloudflare-r2
//                 https://github.com/get-convex/r2#readme
import { R2 } from "@convex-dev/r2";
import { components } from "./_generated/api";
import { mutation } from "./_generated/server";
import type { DataModel, Id } from "./_generated/dataModel";
import { v } from "convex/values";
import { requireUser, requireRole, Forbidden, safeFilename, objectKey } from "./model/auth";
import { appendAudit } from "./model/audit";

export const r2 = new R2(components.r2);

/**
 * Presigned-URL lifetime handed to browsers. This number IS the revocation
 * SLA: an R2 presigned URL is an AWS SigV4 signature over (key, expiry). R2
 * validates the signature and the clock. It performs no lookup against Convex,
 * so it cannot be revoked. Same structural property as a Supabase signed URL.
 */
export const PRESIGNED_TTL_SEC = 30;

/**
 * The R2 component's generated `generateUploadUrl` deliberately does not accept
 * a caller-supplied key ("you don't want your client defining your object
 * keys" -- component README). We need keys namespaced by org, so per the
 * README we write our own mutation that calls `r2.generateUploadUrl(key)`.
 *
 * The document row is created FIRST so that the key can embed its id and so
 * that a later `syncMetadata` has something to attach to.
 */
export const startUpload = mutation({
  args: {
    orgId: v.id("orgs"),
    filename: v.string(),
    mimeType: v.optional(v.string()),
    sizeBytes: v.optional(v.number()),
  },
  handler: async (ctx, args) => {
    const user = await requireUser(ctx);
    // Viewers may not upload. Omitting this line is a silent privilege bug.
    await requireRole(ctx, args.orgId, user._id, "member");

    const filename = safeFilename(args.filename);
    const documentId: Id<"documents"> = await ctx.db.insert("documents", {
      orgId: args.orgId,
      uploaderId: user._id,
      filename,
      mimeType: args.mimeType,
      sizeBytes: args.sizeBytes,
    });

    const key = objectKey(args.orgId, documentId, filename);
    await ctx.db.patch(documentId, { r2Key: key });

    return { documentId, key, url: await r2.generateUploadUrl(key) };
  },
});

/**
 * Called by the client after the PUT to R2 succeeds. Two problems this cannot
 * solve, both inherent to a client-driven upload:
 *   1. If the client never calls it, the documents row is an orphan pointing
 *      at an object that may or may not exist.
 *   2. Nothing proves the bytes at `key` are the bytes the client claimed.
 *      Content-Length and mime type are self-reported at startUpload time.
 */
export const finishUpload = mutation({
  args: { documentId: v.id("documents") },
  handler: async (ctx, args) => {
    const user = await requireUser(ctx);
    const doc = await ctx.db.get(args.documentId);
    // ctx.db.get returns ANY document by id. Without the next two lines a user
    // in org B finalises (and audits into) a document in org A.
    if (doc === null || doc.r2Key === undefined) throw new Forbidden("Not found");
    if (doc.uploaderId !== user._id) throw new Forbidden();

    // The client also calls the component's generated `syncMetadata` mutation
    // with this key, which populates the component's metadata table. That is a
    // third client round-trip on top of startUpload + PUT + finishUpload.
    await appendAudit(ctx, {
      orgId: doc.orgId,
      actorId: user._id,
      actorKind: "user",
      action: "upload",
      subject: { documentId: args.documentId, key: doc.r2Key },
    });
    return { ok: true };
  },
});

/** Read-side helper used by the HTTP actions. Never exposed to clients. */
export async function presign(key: string): Promise<string> {
  return r2.getUrl(key, { expiresIn: PRESIGNED_TTL_SEC });
}

/**
 * The component's client API. `checkUpload` is the component's own hook for
 * gating uploads; we keep it as defence in depth even though `startUpload`
 * above is the path we actually use.
 */
export const { generateUploadUrl, syncMetadata } = r2.clientApi<DataModel>({
  checkUpload: async (ctx, _bucket) => {
    await requireUser(ctx as any);
  },
});
